using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Windows.Forms;using System.Drawing;using System.Reflection;using Frociart;
internal static class OutputContinuationTests {
 static int checks;static void Check(bool b,string s){if(!b)throw new Exception(s);checks++;}static string Normalize(string s){return s.Replace("\r\n","\n");}
 static Interpreter Run(Diagram d,string[] inputs){var r=new Interpreter(d);int at=0;for(int i=0;i<10000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++){if(r.State==RuntimeState.WaitingForInput)r.ProvideInput(inputs[at++]);else r.Step();}Check(r.State==RuntimeState.Completed,"Execution completes: "+r.Error);return r;}
 static void Pump(){var t=System.Diagnostics.Stopwatch.StartNew();while(t.ElapsedMilliseconds<280){Application.DoEvents();System.Threading.Thread.Sleep(5);}}
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public;static object Get(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Call(object o,string n,params object[] args){return o.GetType().GetMethod(n,F).Invoke(o,args);}
 [STAThread]static int Main(string[] args){try{string root=args[0],outdir=Path.Combine(root,"pc");Directory.CreateDirectory(outdir);foreach(string line in File.ReadAllLines(Path.Combine(root,"cases.tsv"),Encoding.UTF8)){
  var row=line.Split('\t');string name=row[0],expected=(string)ExpressionLanguage.Evaluate(row[1],null);string[] inputs=row[3].Length==0?new string[0]:row[3].Split('|');var d=FlowPseudocode.Decode(File.ReadAllText(Path.Combine(root,"fixtures",name+".pseudo")));var run=Run(d,inputs);Check(Normalize(run.OutputText)==expected,"Visible text "+name);Check(run.OutputNewlines.Count==run.Output.Count,"Flags for every event");Check(Normalize(String.Concat(run.Output.Select((s,i)=>s+(run.OutputNewlines[i]?"\n":""))))==(string)ExpressionLanguage.Evaluate(row[2],null),"Exact output stream "+name);Check(Object.ReferenceEquals(run.OutputText,run.OutputText),"Repeated text reads cached");Check(Normalize(Run(DiagramIO.Clone(d),inputs).OutputText)==expected,"Clone "+name);var again=FlowPseudocode.Decode(FlowPseudocode.Encode(d));Check(Normalize(Run(again,inputs).OutputText)==expected,"Pseudocode round trip "+name);string file=Path.Combine(outdir,name+".frociart");DiagramIO.Save(file,d);Check(Normalize(Run(DiagramIO.Load(file),inputs).OutputText)==expected,"Save/reopen "+name);var clip=FlowClipboard.Decode(FlowClipboard.Encode(d));Check(Normalize(Run(clip,inputs).OutputText)==expected,"Clipboard byte round trip "+name);var source=FlowSource.Compile(d);var py=FlowPython.Generate(source);var java=FlowJava.Generate(source,File.ReadAllText(Path.Combine(root,"..","frociart-v1-capabilities/pc/Source/JavaRuntime.txt")),row[4]);File.WriteAllText(Path.Combine(outdir,name+".py"),py.Text,new UTF8Encoding(false));string jd=Path.Combine(outdir,name);Directory.CreateDirectory(jd);File.WriteAllText(Path.Combine(jd,row[4]+".java"),java.Text,new UTF8Encoding(false));
  run.Reset();Check(run.Output.Count==0&&run.OutputNewlines.Count==0&&run.OutputText=="","Reset clears buffered output and flags");
 }
 var fromFile=DiagramIO.Load(Path.Combine(root,"import-fixtures/accepted-no-newline.fprg"));Check(Run(fromFile,new string[0]).OutputText=="1"&&!Run(fromFile,new string[0]).OutputNewlines[0],"Import newline=false");
 var spec=FlowPseudocode.Decode("DICHIARA continua: INTERO\ncontinua=2\nSTAMPA_CONTINUA continua");var node=spec.Nodes.First(n=>n.Kind==NodeKind.Output);string rewritten=FlowDeclaration.RewriteNode(node,new Dictionary<string,string>{{"continua","valore"}});Check(rewritten=="continua: valore","Rename preserves instruction prefix");
 using(var main=new MainForm(null,true)){main.Show();Pump();var d=FlowPseudocode.Decode("STAMPA \"A\"\nSTAMPA \"B\"");main.SetDocument(d,null,false);var n=d.Nodes.First(x=>x.Kind==NodeKind.Output);main.Canvas.SelectNode(n.Id);Pump();var option=(CheckBox)Get(main,"outputNewline");Check(option.Visible&&option.Checked,"Native newline option defaults on");option.Checked=false;Check(((TextBox)Get(main,"expression")).Text=="stampa_continua \"A\"","Native toggle updates editable instruction");((Button)Get(main,"applyButton")).PerformClick();Check(!FlowOutput.Newline(main.Project.Nodes.First(x=>x.Id==n.Id).Text),"Native Apply stores mode");Check(Run(main.Project,new string[0]).OutputText=="AB","Native toggle program result");Call(main,"Undo");Check(Normalize(Run(main.Project,new string[0]).OutputText)=="A\nB","Undo restores mode");Call(main,"Redo");Check(Run(main.Project,new string[0]).OutputText=="AB","Redo restores mode");var r=Run(main.Project,new string[0]);main.Runner=r;Call(main,"RefreshRuntime");Check(((TextBox)Get(main,"output")).Text=="AB","Native streamed output uses flags");Check((string)Call(main,"RuntimeOutputText")=="AB","Copy source uses joined result");using(var image=new Bitmap(main.Width,main.Height)){main.DrawToBitmap(image,new Rectangle(0,0,image.Width,image.Height));image.Save(Path.Combine(root,"pc-output-option.png"));}main.SetDocument(DiagramIO.CreateBlank(),null,false);main.Close();}
 var waiting=new Interpreter(FlowPseudocode.Decode("DICHIARA n: INTERO\nSTAMPA_CONTINUA \"X\"\nLEGGI n\nSTAMPA_CONTINUA n"));while(waiting.State!=RuntimeState.WaitingForInput)waiting.Step();Check(waiting.OutputText=="X","Partial output visible before input");Check(!waiting.ProvideInput("abc")&&waiting.State==RuntimeState.WaitingForInput&&waiting.Output.Count==1,"Invalid input preserves partial line without duplicate events");waiting.ProvideInput("7");while(waiting.State!=RuntimeState.Completed&&waiting.State!=RuntimeState.Error)waiting.Step();Check(waiting.OutputText=="X7","Resume appends on same line");
 var limit=RunUntilError(FlowPseudocode.Decode("s=\""+new string('x',8000)+"\"\nPER i DA 1 A 40 FAI\nSTAMPA_CONTINUA s\nFINE PER"));Check(limit.State==RuntimeState.Error&&limit.Output.Count==32&&limit.OutputText.Length==256000,"Output quota preserves previous fragments atomically");
 var many=Run(FlowPseudocode.Decode("PER i DA 1 A 2000 FAI\nSTAMPA_CONTINUA \"x\"\nFINE PER"),new string[0]);Check(many.OutputText.Length==2000&&many.Output.Count==2000,"Two thousand fragments retain full content");
 bool rejected=false;try{FlowOutput.Toggle(new string('x',8192),NodeKind.Output,false);}catch(FlowException){rejected=true;}Check(rejected,"Toggle refuses truncation of long expression");Console.WriteLine("CONTINUATION_PC PASS checks="+checks);return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}}
 static Interpreter RunUntilError(Diagram d){var r=new Interpreter(d);for(int i=0;i<10000&&r.State!=RuntimeState.Completed&&r.State!=RuntimeState.Error;i++)r.Step();return r;}
}
